page-template.event-handler:
            function onActivated() : boolean {
				page.AllowMoveNext = false;
				if ( File.Exists( Path.Combine( AppDomain.CurrentDomain.BaseDirectory, 'data.zip' )))
				{
					page.errorProvider.SetError( page.pathTextBox, String.Empty );
					page.informationBox.Text = 'Data.zip was found:';
					page.pathTextBox.Text = Path.Combine( AppDomain.CurrentDomain.BaseDirectory, 'data.zip' );
				}
				else
				{
					page.errorProvider.SetError( page.pathTextBox, 'Please specify a valid data file.' );
					page.informationBox.Text = 'Data.zip was not found:';
					page.pathTextBox.Text = 'Please Select data file location...';
					page.AllowMoveNext = false;
				}
				if( !Directory.Exists( rix.project.InstallPath ) ) {
					try {
						System.IO.Directory.CreateDirectory( rix.project.InstallPath );
					}
					catch( e : Exception ) {
						return false;
					}
				}
                return false;
            }

			function onValidate() : boolean {
                if( !File.Exists( Path.Combine( AppDomain.CurrentDomain.BaseDirectory, 'data.zip' )) ) {
                    page.errorProvider.SetError( page.pathTextBox, 'Please specify a valid data file.' );
					System.Windows.Forms.MessageBox.Show('Please select a data file.');
					return false;
                }
                return true;
            }

element.event-handler:
                    function onBrowseClicked( sender : Object, args : EventArgs ) : void {
                        var browser : System.Windows.Forms.OpenFileDialog = new System.Windows.Forms.OpenFileDialog();
                        browser.InitialDirectory = AppDomain.CurrentDomain.BaseDirectory;
						browser.Filter = "zip files (*.zip)|*.zip|All files (*.*)|*.*" ;
                        if( browser.ShowDialog() == System.Windows.Forms.DialogResult.OK ) {
                            page.pathTextBox.Text = browser.FileName;
							var dataFilePath = Path.Combine( AppDomain.CurrentDomain.BaseDirectory, 'data.zip' )
							if( dataFilePath != browser.FileName )
							{
								if (File.Exists(dataFilePath))
								{
									File.Delete(dataFilePath);
								}
								File.Copy(browser.FileName, dataFilePath);
							}
							page.errorProvider.SetError( page.pathTextBox, String.Empty );
							page.informationBox.Text = 'Data file was found:';
                        }
                    }

page-template.event-handler:
            function onActivated() : boolean {
				showProfile( Path.Combine( AppDomain.CurrentDomain.BaseDirectory, 'kiosk-profile.json' ) );
                return false;
            }

            function onDeactivated() : void {
				var kioskId : String = rix.readJsonValue( Path.Combine( AppDomain.CurrentDomain.BaseDirectory, 'kiosk-profile.json' ), 'KioskId' );
				if ( !String.IsNullOrEmpty( kioskId ) ) {
					rix.macros["StoreNumber"] = kioskId;
				}
            }

			function onValidate() : boolean {
				var profilePath = Path.Combine( AppDomain.CurrentDomain.BaseDirectory, 'kiosk-profile.json' );
                if( !File.Exists( profilePath ) || String.IsNullOrEmpty( rix.readJsonValue( profilePath, 'KioskId' ) ) ) {
                    page.errorProvider.SetError( page.pathTextBox, 'Please specify a valid kiosk profile.' );
					System.Windows.Forms.MessageBox.Show('Please select a kiosk profile.');
					return false;
                }
                return true;
            }

page-template.script:
function showProfile( profilePath : String ) : void {
	var kioskId : String = rix.readJsonValue( profilePath, 'KioskId' );
	if ( !String.IsNullOrEmpty( kioskId ) )
	{
		page.errorProvider.SetError( page.pathTextBox, String.Empty );
		page.informationBox.Text = 'Kiosk profile for kiosk ' + kioskId + ' was found:';
		page.pathTextBox.Text = profilePath;
	}
	else
	{
		page.errorProvider.SetError( page.pathTextBox, 'Please specify a valid kiosk profile.' );
		page.informationBox.Text = 'Kiosk-profile.json was not found:';
		page.pathTextBox.Text = 'Please select the kiosk profile...';
	}
}

element.event-handler:
                    function onBrowseClicked( sender : Object, args : EventArgs ) : void {
                        var browser : System.Windows.Forms.OpenFileDialog = new System.Windows.Forms.OpenFileDialog();
                        browser.InitialDirectory = AppDomain.CurrentDomain.BaseDirectory;
						browser.Filter = "kiosk profiles (*.json)|*.json|All files (*.*)|*.*" ;
                        if( browser.ShowDialog() == System.Windows.Forms.DialogResult.OK ) {
							var profilePath = Path.Combine( AppDomain.CurrentDomain.BaseDirectory, 'kiosk-profile.json' )
							if( profilePath != browser.FileName )
							{
								if (File.Exists(profilePath))
								{
									File.Delete(profilePath);
								}
								File.Copy(browser.FileName, profilePath);
							}
							showProfile( profilePath );
                        }
                    }

page-template.event-handler:
function onActivated() : boolean {
    rix.launchprocess( "control", "timedate.cpl" );
    return false;
}

            function onActivated() : boolean {
				page.informationBox.Text = "Please select a kiosk type:"
				if (page.R630RadioButton.Checked || page.R504RadioButton.Checked) {
					page.errorProvider.SetError( page.R630RadioButton, '' );
					page.errorProvider.SetError( page.R504RadioButton, '' );
				}
				page.R630RadioButton.Checked = true;
				return false;
            }

            function onDeactivated() : void {
				var value = "";
				if (page.R630RadioButton.Checked) {	value = "90" }
				if (page.R504RadioButton.Checked) {	value = "72" }
				var ignoreMaxSlots = rix.macros["ignoreMaxSlots"];
				if ( String.IsNullOrEmpty( ignoreMaxSlots ) || String.Compare( ignoreMaxSlots, "undefined" ) == 0 ){
					rix.SetLocalMachineRegistry("SOFTWARE\\Redbox\\REDS\\Kiosk Engine\\Store","MaxSlots", value);
				}
            }

			function onValidate() : boolean {
				if (!page.R630RadioButton.Checked && !page.R504RadioButton.Checked) {
					page.errorProvider.SetError( page.R630RadioButton, 'Please specify a kiosk type.' );
					page.errorProvider.SetError( page.R504RadioButton, 'Please specify a kiosk type.' );
					System.Windows.Forms.MessageBox.Show('Please specify a kiosk type.');
					return false;
				}
				page.errorProvider.SetError( page.R630RadioButton, '' );
				page.errorProvider.SetError( page.R504RadioButton, '' );
                return true;
            }
